window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[70]={"id":"070","numero":70,"titre":"Troubles psychiques du sujet âgé","objectifs":[{"id":"70-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des troubles psychiatriques du sujet âgé","contenu":"<p>La <strong><span class=\"kw-def\">psychiatrie de la personne âgée</span></strong> (ou <span class=\"kw-def\">gérontopsychiatrie</span>) est une sur-spécialisation récente de la psychiatrie. Sa définition, proposée par l'<span class=\"kw-def\">OMS</span> en <span class=\"kw-chiffre\">1996</span>, en fait « la branche de la psychiatrie qui a pour objectifs de <strong>dépister, traiter, évaluer et prévenir</strong> tous <span class=\"kw-clinique\">les</span> types de troubles psychiatriques du sujet âgé et leurs conséquences ».</p>\n      <p>Elle couvre <strong>deux champs</strong> distincts :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">les</span> <strong><span class=\"kw-clinique\">symptômes psycho-comportementaux des démences (SPCD)</span></strong> — c'est-à-dire les troubles neurocognitifs majeurs ;</li>\n        <li>l'ensemble des <span class=\"kw-def\">troubles psychiatriques de la personne âgée</span>, dont l'âge seuil est fixé à <span class=\"kw-chiffre\">&ge; 65 ans</span>.</li>\n      </ul>\n      <h4>Deux grands types de troubles psychiatriques du sujet âgé</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Description</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Troubles anciens vieillissants</strong></td><td>Apparus à un âge plus jeune et qui évoluent avec le vieillissement</td><td><span class=\"kw-etio\">schizophrénie</span> ; <span class=\"kw-etio\">trouble bipolaire</span></td></tr>\n          <tr><td><strong>Troubles à début tardif</strong></td><td>Se déclarent tardivement, à un âge avancé</td><td>formes tardives de <span class=\"kw-etio\">schizophrénie</span> ou d'<span class=\"kw-etio\">EDC</span></td></tr>\n        </tbody>\n      </table>\n      <h4>Caractéristiques du vieillissement à prendre en compte</h4>\n      <ul>\n        <li><span class=\"kw-etio\">événements de vie</span> de type perte, deuil ;</li>\n        <li><span class=\"kw-etio\">fragilisation</span> psychologique et corporelle, perte d'autonomie, difficultés financières ;</li>\n        <li>forte <span class=\"kw-etio\">comorbidité</span> entre troubles psychiatriques et pathologies non psychiatriques ;</li>\n        <li><span class=\"kw-alerte\">risque iatrogène</span> à toujours considérer chez le sujet âgé.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 132 — Troubles cognitifs du sujet âgé</em></p>","frequence":0},{"id":"70-2","rang":"B","rubrique":"Épidémiologie","titre":"Connaître la prévalence des troubles psychiatriques du sujet âgé","contenu":"<p>L'<strong><span class=\"kw-etio\">épisode dépressif caractérisé (EDC)</span></strong> est le <strong>trouble psychiatrique le plus fréquent</strong> du patient âgé. <span class=\"kw-clinique\">Les</span> prévalences des principaux troubles sont à connaître.</p>\n      <table >\n        <thead><tr><th>Trouble</th><th><span class=\"kw-def\">Prévalence</span> chez le sujet âgé</th></tr></thead>\n        <tbody>\n          <tr><td><strong>EDC</strong> (&ge;<span class=\"kw-chiffre\"> 65 ans</span>)</td><td><span class=\"kw-chiffre\">1-5 %</span></td></tr>\n          <tr><td>Symptômes dépressifs (&ge;<span class=\"kw-chiffre\"> 65 ans</span>)</td><td><span class=\"kw-chiffre\">10 %</span></td></tr>\n          <tr><td>EDC chez le patient âgé hospitalisé</td><td><span class=\"kw-chiffre\">25 %</span></td></tr>\n          <tr><td>EDC en EHPAD</td><td><span class=\"kw-chiffre\">40 %</span></td></tr>\n          <tr><td><strong>Troubles anxieux</strong></td><td><span class=\"kw-chiffre\">&gt; 10 %</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Schizophrénie</span></strong></td><td><span class=\"kw-chiffre\">0,6 %</span> (<span class=\"kw-bio\">vs</span><span class=\"kw-chiffre\"> 1 %</span> chez l'adulte jeune)</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Trouble bipolaire</span></strong> (&gt;<span class=\"kw-chiffre\"> 60 ans</span>)</td><td>environ <span class=\"kw-chiffre\">1 %</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> La <span class=\"kw-def\">prévalence</span> de la <span class=\"kw-etio\">schizophrénie</span> et du <span class=\"kw-etio\">trouble bipolaire</span> <strong>diminue avec l'âge</strong> : cet écart s'explique par une <span class=\"kw-alerte\">surmortalité prématurée</span> (suicide, <span class=\"kw-def\">comorbidités</span> non psychiatriques) avant <span class=\"kw-chiffre\">65 ans</span>.</div>","frequence":0},{"id":"70-3","rang":"B","rubrique":"Épidémiologie","titre":"Connaître la prévalence des symptômes psycho-comportementaux chez le sujet âgé dément","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-clinique\">symptômes psycho-comportementaux des démences (SPCD)</span></strong> font partie intégrante du tableau clinique des démences — ce ne sont <strong>pas</strong> de simples <span class=\"kw-def\">comorbidités</span> psychiatriques.</p>\n      <ul>\n        <li>ils sont présents chez <strong><span class=\"kw-chiffre\">&gt; 80 %</span> des patients</strong> atteints de <span class=\"kw-etio\">maladie d'Alzheimer</span> ou de pathologies apparentées ;</li>\n        <li><span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">symptômes de retrait</span> sont les SPCD <strong>précoces</strong> les plus fréquents : ils concernent <span class=\"kw-chiffre\">50 %</span> des démences ;</li>\n        <li>la <span class=\"kw-etio\">dépression</span> est fréquente au cours d'une maladie neurodégénérative : <span class=\"kw-chiffre\">45 %</span> dans la <span class=\"kw-etio\">maladie d'Alzheimer</span>.</li>\n      </ul>","frequence":0},{"id":"70-4","rang":"B","rubrique":"Épidémiologie","titre":"Connaître les spécificités en matière de facteurs de risque, de pronostic et d’évolution des troubles psychiatriques du sujet âgé","contenu":"<h4><span class=\"kw-def\">Facteurs de risque</span> de <span class=\"kw-etio\">dépression</span></h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Âge</strong></td><td><span class=\"kw-alerte\">L'âge n'est PAS un facteur de risque de dépression</span>, contrairement aux idées reçues</td></tr>\n          <tr><td><span class=\"kw-etio\">Pathologies organiques</span></td><td><strong>Cardiovasculaire :</strong> <span class=\"kw-etio\">IDM</span> ; <span class=\"kw-etio\">insuffisance cardiaque</span> ; cancer<br><strong>Neurologique :</strong> <span class=\"kw-etio\">AVC</span> ; troubles neurocognitifs ; Parkinson ; hydrocéphalie à pression normale<br><strong>Endocrino-métabolique :</strong> <span class=\"kw-etio\">diabète</span> ; dysthyroïdie ; hyperparathyroïdie ; hypercorticisme ; déficit androgénique</td></tr>\n          <tr><td><span class=\"kw-etio\">Médicaments</span></td><td><span class=\"kw-ttt\">neuroleptiques</span> ; <span class=\"kw-ttt\">corticoïdes</span> ; <span class=\"kw-ttt\">β-bloquants</span> ; <span class=\"kw-ttt\">L-DOPA</span> ; <span class=\"kw-ttt\">amantadine</span> ; <span class=\"kw-ttt\">clonidine</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Autres</span></td><td>perte d'autonomie ; douleurs chroniques ; ATCD de <span class=\"kw-etio\">dépression</span> ; événements de vie stressants — décès de proches, <strong>entrée en institution</strong></td></tr>\n        </tbody>\n      </table>\n      <h4><span class=\"kw-def\">Pronostic</span> de l'EDC</h4>\n      <ul>\n        <li><strong>Mauvais <span class=\"kw-def\">pronostic</span></strong> : <span class=\"kw-chiffre\">30 %</span> de chronicisation, <span class=\"kw-chiffre\">30 %</span> de rechute ;</li>\n        <li>coûteux : surconsommation de soins, institutionnalisation ;</li>\n        <li>associé à un moins bon <span class=\"kw-alerte\">pronostic vital</span> de plusieurs maladies (<span class=\"kw-etio\">IDM</span>, <span class=\"kw-etio\">AVC</span>, <span class=\"kw-etio\">BPCO</span>) ;</li>\n        <li><span class=\"kw-alerte\">surmortalité générale de 30 %</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 ans</span> suivant l'EDC.</li>\n      </ul>\n      <table >\n        <thead><tr><th>FR de chronicité (<span class=\"kw-chiffre\">30 %</span>)</th><th>FR de rechute (<span class=\"kw-chiffre\">30 %</span>)</th></tr></thead>\n        <tbody>\n          <tr><td>troubles cognitifs ; <strong>pauvreté des relations sociales</strong> ; ralentissement psychomoteur ; limitations fonctionnelles ; sévérité des symptômes dépressifs</td><td>troubles cognitifs ; EI des traitements ; mauvaise observance ; durée trop courte du traitement antidépresseur ; st<span class=\"kw-chiffre\">igm</span>atisation de la <span class=\"kw-etio\">dépression</span> ; absence de soutien familial</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Risques évolutifs.</strong> Le <span class=\"kw-alerte\">risque suicidaire</span> est élevé : probabilité beaucoup plus grande de <strong>suicide abouti</strong> lors d'un passage à l'acte — le ratio tentatives/suicides est de <span class=\"kw-chiffre\">4/1</span> chez le sujet âgé contre <span class=\"kw-chiffre\">20/1</span> en population générale. Un <span class=\"kw-clinique\">EDC tardif</span> (&ge;<span class=\"kw-chiffre\"> 65 ans</span>) augmente aussi le risque d'<span class=\"kw-clinique\">évolution</span> vers une <span class=\"kw-etio\">maladie d'Alzheimer</span> ou une pathologie apparentée.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 353 — Risque et conduite suicidaire · 132 — Troubles cognitifs du sujet âgé</em></p>","frequence":0},{"id":"70-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les spécificités sémiologiques des troubles psychiatriques du sujet âgé","contenu":"<p><strong>Principe général.</strong> L'EDC du sujet âgé est souvent <span class=\"kw-alerte\">sous-diagnostiqué (50 %)</span>, en raison d'idées reçues sur la normalité d'une tristesse ou d'une anhédonie avec le vieillissement, et de nombreux tableaux atypiques. <span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-def\">critères diagnostiques</span> de l'EDC restent les mêmes que chez l'adulte</strong>.</p>\n\n      <h4><span class=\"kw-etio\">Dépression</span> — symptomatologie</h4>\n      <table >\n        <thead><tr><th>Symptômes communs à tout âge</th><th>Symptômes plus spécifiques au sujet âgé</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">tristesse</span>, douleur morale, pessimisme, désespoir ; sentiment d'inutilité, mésestime de soi, <span class=\"kw-clinique\">anhédonie</span> ; <span class=\"kw-clinique\">ralentissement psychomoteur</span> ; <span class=\"kw-clinique\">anorexie</span>, <span class=\"kw-clinique\">perte de poids</span>, troubles du sommeil</td>\n            <td><strong>Douleur morale :</strong> sentiment d'impuissance et d'inutilité ; sensation douloureuse de vide intérieur<br><strong>Troubles du comportement :</strong> irritabilité, agressivité, agitation ; opposition ou refus (alimentation, soin, traitement)<br><strong>Autres :</strong> angoisse matinale, hypochondrie, somatisations ; plaintes mnésiques ; repli sur soi, prostration, <span class=\"kw-def\">isolement</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Symptômes psychotiques.</strong> Des idées délirantes peuvent être présentes, le plus souvent sur des thématiques de <span class=\"kw-clinique\">préjudice</span>, <span class=\"kw-clinique\">persécution</span>, <span class=\"kw-clinique\">jalousie</span>, <span class=\"kw-clinique\">culpabilité</span>, de registre <span class=\"kw-clinique\">hypocondriaque</span>, ou un <strong><span class=\"kw-etio\">syndrome de Cotard</span></strong>.</div>\n\n      <h4>Tableaux cliniques particuliers de <span class=\"kw-etio\">dépression</span></h4>\n      <table >\n        <thead><tr><th>Forme</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Dépression</span> avec TNCM</strong></td><td>Fréquente au cours d'une maladie neurodégénérative (<span class=\"kw-chiffre\">45 %</span> si Alzheimer). <span class=\"kw-alerte\">Risque de retard ou d'excès diagnostique</span> : <span class=\"kw-clinique\">les</span> deux partagent apathie, anhédonie, agitation, ralentissement idéo-moteur, déambulation, <span class=\"kw-clinique\">perte de poids</span>, insomnie</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Dépression</span> masquée</strong></td><td>Perte d'autonomie et plaintes somatiques (douleurs, <span class=\"kw-clinique\">dyspnée</span>) au 1er plan ; la souffrance psychique, en particulier la tristesse, n'est pas exprimée</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Dépression</span> hostile</strong></td><td>Anxiété, récriminations, agitation hostile, refus de soins ; <strong>agressivité dirigée contre l'entourage direct</strong>. La <span class=\"kw-clinique\">modification récente du comportement</span> oriente vers la <span class=\"kw-etio\">dépression</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Dépression</span> avec plainte mnésique</strong></td><td>La plainte mnésique est un symptôme de <span class=\"kw-etio\">dépression</span> du sujet âgé — constitue un <span class=\"kw-alerte\">diagnostic différentiel avec le TNC</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Crise suicidaire</h4>\n      <div class=\"callout callout-danger\"><strong>Ne jamais banaliser.</strong> <span class=\"kw-clinique\">Les</span> personnes âgées <strong>expriment rarement</strong> des idées suicidaires, ou ont rarement l'occasion de les exprimer. <span class=\"kw-chiffre\">30 %</span> des suicides surviennent chez les &ge;<span class=\"kw-chiffre\"> 65 ans</span>, avec une prédominance <strong>masculine</strong>. Particularités : <span class=\"kw-alerte\">intentionnalité suicidaire élevée</span> (réussite des suicides <span class=\"kw-chiffre\">50× supérieure</span> à celle d'un jeune), faible impulsivité et agressivité, peu d'ATCD personnels de conduite suicidaire ; moyens employés souvent <strong>radicaux</strong>.</div>\n\n      <h4><span class=\"kw-etio\">Schizophrénie</span> du sujet âgé</h4>\n      <p>Le diagnostic repose sur <span class=\"kw-clinique\">les</span> <strong>mêmes critères</strong> que chez le sujet jeune.</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Schizophrénie</span> vieillissante</strong></td><td>Sujet ayant déclenché sa <span class=\"kw-etio\">schizophrénie</span> au début de l'âge adulte — symptômes <strong>identiques</strong> à ceux du sujet jeune</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Schizophrénie</span> à début tardif</strong></td><td><strong>Âge :</strong> début tardif <span class=\"kw-chiffre\">&gt; 40 ans</span>, très tardif <span class=\"kw-chiffre\">&gt; 60 ans</span><br><strong>Sexe :</strong> prédominance féminine (<span class=\"kw-chiffre\">7 F / 1 H</span>)<br><strong>Clinique :</strong> idées délirantes de <span class=\"kw-clinique\">persécution</span> ; symptomatologie <span class=\"kw-clinique\">hallucinatoire</span> riche dans toutes <span class=\"kw-clinique\">les</span> modalités sensorielles ; <strong>peu de désorganisation et de symptômes négatifs</strong></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Autres troubles</h4>\n      <table >\n        <thead><tr><th>Trouble</th><th>Spécificités sémiologiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Trouble bipolaire</span></strong></td><td>Présentation clinique <strong>diffère peu</strong> de celle de l'adulte jeune ; <span class=\"kw-chiffre\">15-20 %</span> de débuts tardifs (après <span class=\"kw-chiffre\">55 ans</span>)</td></tr>\n          <tr><td><strong>Troubles anxieux</strong></td><td><span class=\"kw-clinique\">TAG</span> et <span class=\"kw-clinique\">phobies</span> sont <span class=\"kw-clinique\">les</span> plus fréquents ; le trouble panique est rare</td></tr>\n          <tr><td><strong>Trouble lié à l'usage d'<span class=\"kw-etio\">alcool</span></strong></td><td>Certains critères d'addiction de l'adulte jeune ne sont pas applicables (retentissement professionnel, notion de tolérance). Être vigilant : retentissement fonctionnel, négligence corporelle, troubles du sommeil, symptômes anxio-dépressifs, déficit cognitif, <span class=\"kw-etio\">syndrome confusionnel</span>, signes de <span class=\"kw-ttt\">sevrage</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 66 — Trouble dépressif · 63 — Trouble schizophrénique · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 353 — Risque et conduite suicidaire</em></p>","frequence":3},{"id":"70-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la sémiologie des symptômes psycho-comportementaux chez le sujet âgé dément","contenu":"<p><span class=\"kw-clinique\">Les</span> SPCD se regroupent en <strong>trois catégories</strong> sémiologiques.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Symptômes de retrait</strong><br><span class=\"kw-chiffre\">SPCD précoces</span>, <span class=\"kw-clinique\">les</span> plus fréquents (<span class=\"kw-chiffre\">50 %</span> des démences)</td>\n            <td><strong><span class=\"kw-clinique\">Apathie</span> :</strong> <span class=\"kw-ttt\">réduction</span> quantifiable des initiatives et des activités dirigées vers un but (comportements, cognitions, émotions, interactions sociales). <span class=\"kw-alerte\">≠ anhédonie</span> : l'apathie n'est pas un symptôme dépressif, le sujet n'en souffre pas (indifférence émotionnelle)<br><strong>Symptômes dépressifs :</strong> tristesse, culpabilité, pessimisme, idées de mort</td>\n          </tr>\n          <tr>\n            <td><strong>Symptômes psychotiques</strong><br><span class=\"kw-chiffre\">SPCD tardifs</span></td>\n            <td><strong>Idées délirantes :</strong> idées de <span class=\"kw-clinique\">persécution</span> ; <strong><span class=\"kw-def\">perturbations de l'identification</span></strong> = interprétation erronée liée aux altérations mnésiques et sensorielles (conviction d'être volé, conviction d'occuper un domicile qui n'est pas le sien)<br><strong>Hallucinations :</strong> surtout <span class=\"kw-clinique\">visuelles</span>, favorisées par <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">déficits sensoriels</span> qu'il convient de corriger</td>\n          </tr>\n          <tr>\n            <td><strong>Autres symptômes</strong></td>\n            <td><strong>Anxiété :</strong> attaques de panique, ruminations, cris, questionnements répétitifs ; agitation, agressivité, irritabilité (accès de colère)<br><strong>Euphorie / désinhibition :</strong> impulsivité et hyper-familiarité avec perte des convenances → <span class=\"kw-alerte\">syndrome frontal</span><br><strong>Autres :</strong> comportements moteurs aberrants (stéréotypies), troubles du sommeil et de l'appétit</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Devant des <span class=\"kw-clinique\">hallucinations visuelles</span>, évoquer un <span class=\"kw-etio\">syndrome confusionnel</span> ou une <span class=\"kw-etio\">démence à corps de Lewy</span>. <span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">perturbations de l'identification</span> ne doivent <strong>pas</strong> être traitées par neuroleptiques.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 132 — Troubles cognitifs du sujet âgé</em></p>","frequence":0},{"id":"70-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les spécificités du diagnostic différentiel et comorbide chez le sujet âgé","contenu":"<div class=\"callout callout-danger\"><strong><span class=\"kw-etio\">Syndrome confusionnel</span> — principal <span class=\"kw-def\">diagnostic différentiel</span> des SPCD.</strong> Il associe altérations cognitives et manifestations psychiatriques (agitation, hallucinations). Éléments distinctifs : <span class=\"kw-alerte\">apparition brutale</span> en rapport avec une affection médicale non psychiatrique aiguë ; symptômes <span class=\"kw-alerte\">fluctuants dans la journée</span> ; <span class=\"kw-clinique\">altération de la vigilance</span> et <span class=\"kw-clinique\">désorientation temporo-spatiale</span> marquées.</div>\n      <h4>Diagnostics différentiels des symptômes psychotiques du sujet âgé</h4>\n      <table >\n        <thead><tr><th>Origine</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Psychiatrique</span></td><td>troubles de l'humeur avec caractéristiques psychotiques ; <strong><span class=\"kw-etio\">trouble délirant persistant</span></strong> — plus fréquent chez le sujet âgé (pas de désorganisation ni de syndrome négatif)</td></tr>\n          <tr><td><span class=\"kw-etio\">Démences</span></td><td><strong><span class=\"kw-etio\">maladie d'Alzheimer</span></strong> = <span class=\"kw-alerte\">1ère cause de symptômes psychotiques du sujet âgé</span> ; <span class=\"kw-etio\">démence à corps de Lewy</span> = hallucinations visuelles précoces</td></tr>\n          <tr><td><span class=\"kw-etio\">Non psychiatrique</span></td><td><span class=\"kw-etio\">syndrome confusionnel</span> ; pathologies neurologiques, métaboliques, endocriniennes ; morphiniques, psychotropes ; <span class=\"kw-ttt\">sevrage</span> en BZD ou <span class=\"kw-etio\">alcool</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Comorbidité</span>.</strong> La <strong>forte comorbidité</strong> entre troubles psychiatriques et pathologies non psychiatriques est une spécificité du sujet âgé. Devant des SPCD, toujours rechercher une <span class=\"kw-alerte\">cause médicale non psychiatrique en premier lieu</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 132 — Troubles cognitifs du sujet âgé · 65 — Trouble délirant persistant</em></p>","frequence":0},{"id":"70-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître le bilan clinique et paraclinique spécifique au sujet âgé","contenu":"<h4>Échelles de repérage</h4>\n      <p>L'<strong><span class=\"kw-bio\">échelle de dépression gériatrique (GDS, Geriatric Depression Scale)</span></strong> sert au <strong>repérage</strong> d'un état dépressif chez le sujet âgé, <span class=\"kw-alerte\">mais ne permet pas le diagnostic</span>. Elle existe en versions à <span class=\"kw-chiffre\">30, 15 ou 4 items</span> (<span class=\"kw-clinique\">les</span> versions abrégées sont fortement corrélées à la version complète).</p>\n      <table >\n        <thead><tr><th>Échelle</th><th>Usage</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">GDS</span></td><td>auto-questionnaire de repérage — <span class=\"kw-alerte\">non validé si troubles cognitifs avec MMSE &lt; 15</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Hamilton</span>, <span class=\"kw-bio\">MADRS</span> (Montgomery et Åsberg)</td><td>échelles d'hétéro-évaluation de la <span class=\"kw-etio\">dépression</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Échelle de Cornell</span></td><td>évaluation du risque de <span class=\"kw-etio\">dépression</span> chez le sujet dément</td></tr>\n        </tbody>\n      </table>\n      <h4><span class=\"kw-bio\">GDS</span> — version 4 items</h4>\n      <p>Outil de <span class=\"kw-def\">dépistage</span> rapide ; un <strong><span class=\"kw-def\">score</span> &ge; 1</strong> indique une forte probabilité de <span class=\"kw-etio\">dépression</span>.</p>\n      <table >\n        <thead><tr><th>Question</th><th>Réponse cotée 1 point</th></tr></thead>\n        <tbody>\n          <tr><td>Vous sentez-vous souvent abattu(e) et triste ?</td><td>Oui</td></tr>\n          <tr><td>Avez-vous le sentiment que votre vie est vide ?</td><td>Oui</td></tr>\n          <tr><td>Êtes-vous heureux(se) la plupart du temps ?</td><td><strong>Non</strong></td></tr>\n          <tr><td>Pensez-vous que votre situation est sans espoir ?</td><td>Oui</td></tr>\n        </tbody>\n      </table>\n      <p>Interprétation : <span class=\"kw-chiffre\">score = 0</span> → peu de risque de <span class=\"kw-etio\">dépression</span> ; <span class=\"kw-chiffre\">score &ge; 1</span> → <span class=\"kw-etio\">dépression</span> probable, évaluation approfondie nécessaire.</p>\n      <div class=\"callout callout-warn\"><strong>Enquête étiologique devant des SPCD.</strong> <span class=\"kw-clinique\">Les</span> SPCD ont souvent une <strong>origine multifactorielle</strong> et doivent faire l'objet d'une enquête étiologique : les <span class=\"kw-alerte\">causes médicales non psychiatriques sont à rechercher en premier lieu</span>.</div>\n      <h4>Bilan paraclinique éliminant une cause non psychiatrique</h4>\n      <p>Des <strong>troubles ioniques, métaboliques, neurologiques et cardiovasculaires</strong> doivent être systématiquement recherchés. Un <strong>examen clinique complet</strong> est indispensable et oriente le bilan paraclinique, demandé <span class=\"kw-alerte\">selon les points d'appel</span>.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Recherche</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">NFS</span></td><td>anémie, <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span>, hémopathie</td></tr>\n          <tr><td><span class=\"kw-bio\">Ionogramme sanguin</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">albuminémie</span></td><td>troubles ioniques et métaboliques (<span class=\"kw-bio\">calcémie</span> à corriger sur l'albuminémie)</td></tr>\n          <tr><td><span class=\"kw-bio\">TSH</span></td><td>dysthyroïdie</td></tr>\n          <tr><td><span class=\"kw-bio\">Vitamines B9-B12</span></td><td>carences (<span class=\"kw-bio\">folates</span>, cobalamine)</td></tr>\n          <tr><td><span class=\"kw-bio\">ECG</span></td><td>bilan cardiovasculaire — utile <strong>avant introduction d'un psychotrope</strong></td></tr>\n          <tr><td><span class=\"kw-bio\">Imagerie cérébrale</span></td><td>cause neurologique selon le contexte</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"70-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les spécificités du maniement des anxiolytiques et hypnotiques chez le sujet âgé","contenu":"<h4>Molécules, durées et effets indésirables</h4>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Spécificités chez le sujet âgé</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Molécules</strong></td><td>privilégier de <strong>faibles posologies</strong> de <span class=\"kw-ttt\">BZD à demi-vie courte</span> (<span class=\"kw-ttt\">oxazépam</span>, <span class=\"kw-ttt\">lorazépam</span>) ; anxiolytiques non-BZD peu utilisés — <span class=\"kw-ci\">hydroxyzine à éviter</span> (effets anticholinergiques)</td></tr>\n          <tr><td><strong>Durée de prescription</strong></td><td><span class=\"kw-chiffre\">12 semaines</span> maximum pour <span class=\"kw-clinique\">les</span> anxiolytiques ; <span class=\"kw-chiffre\">4 semaines</span> maximum pour les hypnotiques</td></tr>\n          <tr><td><strong>Effets indésirables</strong></td><td>sédation, altérations cognitives, amnésie antérograde, <span class=\"kw-etio\">syndrome confusionnel</span> ; <span class=\"kw-alerte\">risque de chutes et de fractures</span> ; dépendance, tolérance, <span class=\"kw-ttt\">sevrage</span></td></tr>\n        </tbody>\n      </table>\n      <h4>Modalités d'arrêt des BZD (patient &gt;<span class=\"kw-chiffre\"> 65 ans</span>)</h4>\n      <table >\n        <thead><tr><th>Étape</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1 · Évaluation de la consommation</strong></td><td><span class=\"kw-def\">critère de</span> <span class=\"kw-def\">réévaluation</span> = <span class=\"kw-chiffre\">prise quotidienne &gt; 30 jours</span> ; si l'indication reste valable → maintien possible sous <span class=\"kw-def\">surveillance</span></td></tr>\n          <tr><td><strong>2 · Décision partagée</strong></td><td>décision conjointe avec le patient (attentes, degré d'attachement aux BZD) pour améliorer l'adhésion au <span class=\"kw-ttt\">sevrage</span></td></tr>\n          <tr><td><strong>3 · Évaluation des difficultés</strong></td><td><strong>Pathologies associées :</strong> <span class=\"kw-etio\">dépression</span> ; insomnie chronique ; trouble anxieux caractérisé ; troubles cognitifs, démence<br><strong>Facteurs de rechute :</strong> échecs antérieurs d'arrêt ; surconsommation d'<span class=\"kw-etio\">alcool</span></td></tr>\n          <tr><td><strong>4 · PEC spécialisée conjointe</strong></td><td>si doses très élevées de BZD, insomnie rebelle, dépendance à l'<span class=\"kw-etio\">alcool</span> ou autre substance, association d'autres psychotropes, troubles psychiatriques sévères</td></tr>\n          <tr><td><strong>5 · Arrêt progressif</strong></td><td>diminution progressive sur <span class=\"kw-chiffre\">4 à 10 semaines</span></td></tr>\n          <tr><td><strong>6 · <span class=\"kw-def\">Suivi</span> rapproché</strong></td><td>consultations rapprochées jusqu'à <span class=\"kw-chiffre\">1 semaine</span> après l'arrêt ; <span class=\"kw-def\">suivi</span> jusqu'à <span class=\"kw-chiffre\">6 mois</span> pour prévenir <span class=\"kw-clinique\">les</span> rechutes</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Pourquoi un arrêt progressif.</strong> Éviter le <span class=\"kw-alerte\">syndrome de sevrage</span> (insomnie, anxiété rebond, agitation) et réduire le risque de chutes, de troubles cognitifs et de dépendance.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 74 — Psychotropes · 131 — Troubles de la marche et de l'équilibre du sujet âgé</em></p>","frequence":0},{"id":"70-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les spécificités du maniement des psychotropes chez le sujet âgé","contenu":"<h4>Principes fondamentaux</h4>\n      <p>Le <span class=\"kw-alerte\">risque iatrogène</span>, lié notamment aux psychotropes, est une préoccupation constante chez le sujet âgé (polymédication, interactions médicamenteuses). Consommation : <span class=\"kw-chiffre\">1/3</span> des &gt;<span class=\"kw-chiffre\"> 65 ans</span> ont une prescription de <span class=\"kw-ttt\">BZD</span>, <span class=\"kw-chiffre\">13 %</span> un <span class=\"kw-ttt\">antidépresseur</span>, <span class=\"kw-chiffre\">3 %</span> un <span class=\"kw-ttt\">antipsychotique</span> ; consommation <span class=\"kw-chiffre\">2× plus importante</span> chez <span class=\"kw-clinique\">les</span> femmes.</p>\n      <ul>\n        <li>règle du <strong>« start low, go slow »</strong> : débuter à une posologie plus faible que chez l'adulte jeune (généralement <span class=\"kw-chiffre\">demi-dose</span>), augmenter lentement ;</li>\n        <li>ne prescrire qu'<strong>un seul psychotrope par classe</strong>, éviter <span class=\"kw-clinique\">les</span> associations ;</li>\n        <li>évaluer régulièrement l'efficacité à l'aide d'échelles validées chez le sujet âgé.</li>\n      </ul>\n      <h4>Spécificités par classe</h4>\n      <table >\n        <thead><tr><th>Classe</th><th>Maniement chez le sujet âgé</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Antipsychotiques</strong></td><td><strong>Molécules :</strong> <span class=\"kw-ttt\">tiapride IM</span> (AMM pour l'agitation du patient âgé) ; 2ᵉ génération en <span class=\"kw-chiffre\">1ère intention</span> — <span class=\"kw-ttt\">rispéridone</span> (<span class=\"kw-ttt\">quétiapine</span>, <span class=\"kw-ttt\">olanzapine</span> possibles) ; <span class=\"kw-ttt\">clozapine</span> si maladie de Parkinson ou démence à corps de Lewy<br><strong>EI :</strong> effets extrapyramidaux ; effets anticholinergiques ; <span class=\"kw-alerte\">surmortalité cardiovasculaire par AVC</span><br><strong>Piège :</strong> non indiqués dans <span class=\"kw-clinique\">les</span> troubles de l'identification</td></tr>\n          <tr><td><strong>Antidépresseurs</strong></td><td><span class=\"kw-ttt\">ISRS</span> en <span class=\"kw-chiffre\">1ère intention</span>, <span class=\"kw-ttt\">IRSNA</span> en cas d'échec ; <span class=\"kw-ci\">tricycliques (imipraminiques) déconseillés</span> chez le sujet âgé — effets anticholinergiques et <span class=\"kw-alerte\">allongement du QT</span></td></tr>\n          <tr><td><strong>Thymorégulateurs</strong></td><td>mêmes règles que chez l'adulte plus jeune ; <span class=\"kw-ttt\">lithium</span> (référence — attention à la <span class=\"kw-bio\">clairance</span> rénale et aux interactions) ; <span class=\"kw-ttt\">anticonvulsivants</span> en alternative</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Psychotropes et SPCD.</strong> <span class=\"kw-clinique\">Les</span> <strong>approches non médicamenteuses sont à privilégier</strong>. Les psychotropes sont réservés aux SPCD avec retentissement sévère, après échec des mesures non pharmacologiques. <span class=\"kw-alerte\">Les antidépresseurs ne sont pas indiqués dans l'apathie</span> (tendance à la majorer). En <span class=\"kw-alerte\">urgence</span> : <span class=\"kw-ttt\">BZD</span> à demi-vie courte faible dose si anxiété majeure ; <span class=\"kw-ttt\">neuroleptique atypique</span> faible dose (rispéridone, <span class=\"kw-ttt\">olanzapine</span>) si délire ou hallucinations avec agitation dangereuse ; <span class=\"kw-ttt\">clozapine</span> si maladie à corps de Lewy ou Parkinson ; <span class=\"kw-ttt\">tiapride IM</span> si voie orale impossible.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 74 — Psychotropes · 132 — Troubles cognitifs du sujet âgé</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Crise suicidaire :</strong> <span class=\"kw-clinique\">les</span> idées suicidaires du sujet âgé <span class=\"kw-alerte\">ne doivent jamais être banalisées</span> ; l'intentionnalité est élevée et la <span class=\"kw-alerte\">réussite des suicides</span> est <span class=\"kw-chiffre\">50x supérieure</span> à celle du jeune (passage à l'acte souvent <span class=\"kw-alerte\">abouti</span>).<br><strong>1er geste :</strong> évaluer le <span class=\"kw-alerte\">risque suicidaire</span> — un <span class=\"kw-etio\">épisode dépressif caractérisé</span> est présent dans <span class=\"kw-chiffre\">90 %</span> des cas — et organiser la mise en sécurité.<br><strong>Agitation aiguë (SPCD) :</strong> si <span class=\"kw-clinique\">délire</span> ou <span class=\"kw-clinique\">hallucinations</span> à l'origine d'une <span class=\"kw-alerte\">agitation compromettant la sécurité</span> du patient ou de l'entourage, traitement <span class=\"kw-etio\">médicamenteux</span> sans délai, après recherche d'une <span class=\"kw-etio\">cause</span>.</p>","hospit":"<p><strong>Ambulatoire :</strong> situation habituelle des <span class=\"kw-def\">SPCD</span> ; <span class=\"kw-ttt\">interventions non médicamenteuses</span> et éducation des proches/soignants en 1re ligne.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> indiquée en cas de <span class=\"kw-alerte\">risque vital</span>, de <span class=\"kw-alerte\">mise en danger</span> du patient ou des proches, lorsqu'une <span class=\"kw-ttt\">modification thérapeutique</span> requiert une <span class=\"kw-def\">surveillance</span> médicale rapprochée, ou en cas de <span class=\"kw-alerte\">risque de maltraitance</span>.<br><strong>PEC spécialisée conjointe :</strong> pour le <span class=\"kw-ttt\">sevrage</span> en <span class=\"kw-ttt\">BZD</span> à doses très élevées, l'insomnie rebelle, la dépendance à l'<span class=\"kw-etio\">alcool</span> ou <span class=\"kw-clinique\">les</span> troubles psychiatriques sévères.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Risque suicidaire</span> : passage à l'acte souvent <span class=\"kw-alerte\">abouti</span>, moyens radicaux (arme à feu, pendaison, défenestration)</li><li><span class=\"kw-etio\">Épisode dépressif caractérisé</span> quasi constant (<span class=\"kw-chiffre\">90 %</span>) précédant la crise suicidaire</li><li><span class=\"kw-clinique\">Agitation</span> / <span class=\"kw-clinique\">agressivité</span> compromettant la sécurité du patient ou de l'entourage</li><li><span class=\"kw-etio\">Syndrome confusionnel</span> (principal <span class=\"kw-def\">diagnostic différentiel</span>) : début <span class=\"kw-clinique\">brutal</span>, symptômes <span class=\"kw-clinique\">fluctuants</span>, <span class=\"kw-clinique\">altération de la vigilance</span> et <span class=\"kw-clinique\">désorientation temporo-spatiale</span></li><li><span class=\"kw-clinique\">Hallucinations visuelles</span> : évoquer un <span class=\"kw-etio\">syndrome confusionnel</span> ou une <span class=\"kw-etio\">démence à corps de Lewy</span></li><li><span class=\"kw-alerte\">Surmortalité générale</span> de <span class=\"kw-chiffre\">30 %</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 ans</span> suivant un EDC du sujet âgé</li></ul>","principes":"<p>Toujours rechercher et traiter une <span class=\"kw-etio\">cause médicale non psychiatrique</span> en premier ; privilégier <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">approches non médicamenteuses</span> ; appliquer la règle <span class=\"kw-ttt\">« start low, go slow »</span> (<span class=\"kw-chiffre\">demi-dose</span>) pour tout psychotrope.</p><p><strong>Dépression du sujet âgé</strong></p><ul><li><span class=\"kw-ttt\">ISRS</span> en 1re intention, pendant <span class=\"kw-chiffre\">≥ 12 mois</span></li><li><span class=\"kw-ttt\">IRSNA</span> en cas d'échec ; <span class=\"kw-ttt\">soutien psychologique</span> / <span class=\"kw-ttt\">psychothérapie</span> associés</li><li><span class=\"kw-ttt\">Électroconvulsivothérapie</span> et <span class=\"kw-ttt\">stimulation magnétique transcrânienne</span> possibles</li><li><span class=\"kw-ci\">Antidépresseurs tricycliques déconseillés</span> (effets <span class=\"kw-ci\">anticholinergiques</span>, <span class=\"kw-ci\">allongement du QT</span>)</li></ul><p><strong>SPCD des démences</strong></p><p><span class=\"kw-ci\">Ne pas traiter les troubles de l'identification par neuroleptiques</span> ; <span class=\"kw-ci\">antidépresseurs non indiqués dans l'apathie</span> (tendance à la majorer)</p><ul><li>Traiter la <span class=\"kw-etio\">cause</span> et privilégier <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">interventions non médicamenteuses</span> (éducation des proches/soignants en EHPAD)</li><li>Anxiété majeure : <span class=\"kw-ttt\">BZD per os à demi-vie courte</span> à faible dose (<span class=\"kw-ttt\">oxazépam</span>, <span class=\"kw-ttt\">alprazolam</span>)</li><li>Délire/hallucinations avec agitation dangereuse : <span class=\"kw-ttt\">neuroleptique atypique per os faible dose</span> (<span class=\"kw-ttt\">rispéridone</span> ou <span class=\"kw-ttt\">olanzapine</span>)</li><li>Si <span class=\"kw-etio\">maladie à corps de Lewy</span> ou <span class=\"kw-etio\">Parkinson</span> : <span class=\"kw-ttt\">clozapine</span> (<span class=\"kw-ci\">neuroleptiques habituels contre-indiqués</span>)</li><li>Si voie per os impossible : <span class=\"kw-ttt\">tiapride IM</span> (le moins anticholinergique, faible dose)</li></ul><p><strong>Maniement des psychotropes</strong></p><ul><li>Règle <span class=\"kw-ttt\">« start low, go slow »</span> : débuter à <span class=\"kw-chiffre\">demi-dose</span>, augmenter lentement, posologie minimale efficace</li><li>Un seul <span class=\"kw-ttt\">psychotrope</span> par classe, éviter <span class=\"kw-clinique\">les</span> associations</li><li>Anxiolytiques : durée <span class=\"kw-chiffre\">≤ 12 semaines</span> ; hypnotiques : <span class=\"kw-chiffre\">≤ 4 semaines</span></li><li><span class=\"kw-ci\">Hydroxyzine à éviter</span> (effets anticholinergiques) ; <span class=\"kw-ttt\">lithium</span> : surveiller la <span class=\"kw-bio\">clairance rénale</span></li></ul><p><strong>Arrêt des BZD (<span class=\"kw-chiffre\">> 65 ans</span>)</strong></p><ul><li>Arrêt <span class=\"kw-ttt\">progressif</span> sur <span class=\"kw-chiffre\">4 à 10 semaines</span> pour éviter le <span class=\"kw-alerte\">syndrome de sevrage</span> et le rebond anxieux</li><li>Décision partagée ; repérer <span class=\"kw-clinique\">les</span> facteurs de difficulté (<span class=\"kw-etio\">dépression</span>, <span class=\"kw-etio\">insomnie chronique</span>, <span class=\"kw-etio\">trouble anxieux</span>, échecs antérieurs)</li><li><span class=\"kw-def\">Suivi</span> rapproché jusqu'à <span class=\"kw-chiffre\">1 semaine</span> après l'arrêt, puis jusqu'à <span class=\"kw-chiffre\">6 mois</span></li></ul>","suivi":"<p><strong>Efficacité :</strong> réévaluer régulièrement à l'aide d'<span class=\"kw-ttt\">échelles validées</span> chez le sujet âgé (l'antidépresseur est aussi efficace que chez le jeune).<br><strong>Tolérance :</strong> surveiller <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">chutes</span>/fractures, la <span class=\"kw-clinique\">sédation</span>, les <span class=\"kw-clinique\">troubles cognitifs</span> / <span class=\"kw-clinique\">syndrome confusionnel</span>, les effets <span class=\"kw-clinique\">extrapyramidaux</span> et la <span class=\"kw-alerte\">surmortalité par AVC</span> sous antipsychotiques.<br><strong>BZD :</strong> <span class=\"kw-def\">suivi</span> du <span class=\"kw-ttt\">sevrage</span> jusqu'à <span class=\"kw-chiffre\">6 mois</span> ; <span class=\"kw-ttt\">lithium</span> : contrôle de la <span class=\"kw-bio\">clairance rénale</span> et des interactions médicamenteuses.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Sujet âgé dément avec SPCD (agitation, délire, anxiété…) — Enquête étiologique d'abord : rechercher une cause médicale non psychiatrique et corriger les déficits sensoriels","detail":"<h4>CAT — Symptômes psycho-comportementaux des démences (SPCD) — Conduite à tenir devant des troubles psycho-comportementaux chez le sujet âgé dément</h4>","branches":[{"to":"q-gravite","label":"Symptômes confirmés","color":"blue"}]},{"id":"q-gravite","kind":"decision","label":"Risque vital, mise en danger du patient/proches ou maltraitance ?","branches":[{"to":"t-hospit","label":"Oui","color":"red"},{"to":"q-mesures","label":"Non","color":"green"}]},{"id":"t-hospit","kind":"terminal","label":"Hospitalisation — Mise en sécurité","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> pour mise en sécurité du patient et de l'entourage</li><li>Indications : <span class=\"kw-alerte\">risque vital</span>, <span class=\"kw-alerte\">mise en danger</span> du patient ou des proches, <span class=\"kw-alerte\">risque de maltraitance</span>, ou <span class=\"kw-ttt\">modification thérapeutique</span> nécessitant une <span class=\"kw-def\">surveillance</span> rapprochée</li></ul>"},{"id":"q-mesures","kind":"decision","label":"Retentissement sévère ou échec des mesures non médicamenteuses ? — Après traitement de la cause","branches":[{"to":"t-nonpharma","label":"Non — symptômes modérés","color":"green"},{"to":"q-type","label":"Oui — sévère ou échec","color":"amber"}]},{"id":"t-nonpharma","kind":"terminal","label":"Mesures non médicamenteuses en ambulatoire — À privilégier","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Éducation des proches et soignants</span> (EHPAD) aux techniques de soins</li><li><span class=\"kw-ttt\">Interventions non médicamenteuses</span> par équipes spécialisées (structures Alzheimer)</li></ul><h4>Conduite</h4><ul><li>Traiter toute <span class=\"kw-etio\">cause médicale non psychiatrique</span> ; corriger <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">déficits sensoriels</span> favorisant les hallucinations</li></ul>"},{"id":"q-type","kind":"decision","label":"Type de symptôme prédominant ?","branches":[{"to":"t-bzd","label":"Anxiété majeure","color":"amber"},{"to":"t-identif","label":"Troubles de l'identification","color":"blue"},{"to":"q-terrain","label":"Délire / hallucinations + agitation dangereuse","color":"amber"}]},{"id":"t-bzd","kind":"terminal","label":"BZD à demi-vie courte, faible dose — Anxiété majeure","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">BZD per os à demi-vie courte</span>, faible dose : <span class=\"kw-ttt\">oxazépam</span>, <span class=\"kw-ttt\">alprazolam</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Risque de <span class=\"kw-alerte\">chutes</span>, <span class=\"kw-clinique\">sédation</span>, <span class=\"kw-clinique\">confusion</span> ; durée de prescription limitée</li></ul>"},{"id":"t-identif","kind":"terminal","label":"Pas de neuroleptique — Troubles de l'identification","color":"blue","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ci\">Ne pas traiter les troubles de l'identification par neuroleptiques</span></li><li>Privilégier une approche relationnelle et <span class=\"kw-ttt\">non médicamenteuse</span></li></ul>"},{"id":"q-terrain","kind":"decision","label":"Maladie de Parkinson ou démence à corps de Lewy ? — Délire / hallucinations + agitation dangereuse","branches":[{"to":"t-clozapine","label":"Oui (Parkinson / corps de Lewy)","color":"red"},{"to":"t-atypique","label":"Non — voie orale possible","color":"amber"},{"to":"t-tiapride","label":"Non — voie orale impossible","color":"amber"}]},{"id":"t-clozapine","kind":"terminal","label":"Clozapine — Parkinson / corps de Lewy","color":"red","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Clozapine</span> : <span class=\"kw-ci\">neuroleptiques habituels contre-indiqués</span> dans le <span class=\"kw-etio\">Parkinson</span> et la <span class=\"kw-etio\">démence à corps de Lewy</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Effets indésirables marqués chez le sujet âgé : <span class=\"kw-clinique\">extrapyramidaux</span>, anticholinergiques, <span class=\"kw-alerte\">surmortalité par AVC</span></li></ul>"},{"id":"t-atypique","kind":"terminal","label":"Neuroleptique atypique per os — Voie orale possible","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Neuroleptique atypique per os faible dose</span> : <span class=\"kw-ttt\">rispéridone</span> (1re intention) ou <span class=\"kw-ttt\">olanzapine</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Posologie minimale efficace ; EI : <span class=\"kw-clinique\">extrapyramidaux</span>, anticholinergiques, <span class=\"kw-alerte\">surmortalité par AVC</span></li></ul>"},{"id":"t-tiapride","kind":"terminal","label":"Tiapride IM — Voie orale impossible","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Tiapride IM</span> : neuroleptique classique le moins anticholinergique, à faible dose (AMM pour l'agitation du sujet âgé)</li></ul>"}]},"cards":[{"i":"104a54bf3f44","n":70,"o":"70-1","u":"Définition","t":"Connaître la définition des troubles psychiatriques du sujet âgé","q":"Quelles sont les caractéristiques du vieillissement à prendre en compte dans la prise en charge des troubles psychiatriques du sujet âgé ?","a":"<ul><li><strong>Événements de vie</strong> spécifiques (perte, deuil).</li><li><strong>Fragilisation</strong> psychologique et corporelle, perte d'autonomie, difficultés financières.</li><li>Forte <strong>comorbidité</strong> entre troubles psychiatriques et pathologies non psychiatriques.</li><li>Risque <strong>iatrogène</strong> toujours à considérer.</li></ul>"},{"i":"7795e8cf4719","n":70,"o":"70-1","u":"Définition","t":"Connaître la définition des troubles psychiatriques du sujet âgé","q":"Quels sont les deux principaux champs couverts par la psychiatrie de la personne âgée ?","a":"<ul><li>Les <strong>symptômes psycho-comportementaux des démences (SPCD)</strong>, ou troubles neurocognitifs majeurs.</li><li>L'ensemble des <strong>troubles psychiatriques de la personne âgée</strong> (à partir de <strong>65 ans</strong>).</li></ul>"},{"i":"7d0aa4f6c0e6","n":70,"o":"70-1","u":"Définition","t":"Connaître la définition des troubles psychiatriques du sujet âgé","q":"Quels sont les deux grands types de troubles psychiatriques distingués chez la personne âgée ?","a":"<ul><li>Les <strong>troubles anciens vieillissants</strong> : apparus plus tôt et évoluant avec le vieillissement (ex: schizophrénie, trouble bipolaire).</li><li>Les <strong>troubles à début tardif</strong> : se déclarant à un âge avancé (ex: formes tardives de schizophrénie ou d'EDC).</li></ul>"},{"i":"854f02e28285","n":70,"o":"70-1","u":"Définition","t":"Connaître la définition des troubles psychiatriques du sujet âgé","q":"Quelle est la définition de la psychiatrie de la personne âgée (ou gérontopsychiatrie) selon l'OMS ?","a":"<p>Selon l'<strong>OMS</strong> (1996), la psychiatrie de la personne âgée est « la branche de la psychiatrie qui a pour objectifs de <strong>dépister, traiter, évaluer et prévenir tous les types de troubles psychiatriques du sujet âgé et leurs conséquences</strong> ».</p>"},{"i":"17c01e70a893","n":70,"o":"70-5","u":"Diagnostic positif","t":"Connaître les spécificités sémiologiques des troubles psychiatriques du sujet âgé","q":"Quelles sont les formes cliniques particulières de dépression chez le sujet âgé ?","a":"<p>On distingue plusieurs formes cliniques particulières de dépression chez le sujet âgé :</p><ul><li>La <strong>dépression avec trouble neurocognitif majeur (TNCM)</strong> : fréquente (<strong>45% si Alzheimer</strong>), partageant des symptômes comme l'apathie, l'anhédonie, le ralentissement idéo-moteur.</li><li>La <strong>dépression masquée</strong> : prédominance des plaintes somatiques (douleurs, dyspnée) et de la perte d'autonomie, la souffrance psychique n'étant pas exprimée.</li><li>La <strong>dépression hostile</strong> : caractérisée par l'anxiété, des récriminations, une agitation hostile, le refus de soins et une agressivité dirigée contre l'entourage.</li><li>La <strong>dépression avec plainte mnésique</strong> : la plainte mnésique est un symptôme de dépression et doit être distinguée d'un TNCM.</li></ul>"},{"i":"1948ea819b64","n":70,"o":"70-5","u":"Diagnostic positif","t":"Connaître les spécificités sémiologiques des troubles psychiatriques du sujet âgé","q":"Quelles sont les spécificités de la schizophrénie du sujet âgé ?","a":"<p>La schizophrénie du sujet âgé se présente sous deux formes principales :</p><ul><li>La <strong>schizophrénie vieillissante</strong> : il s'agit d'une forme débutée à l'âge adulte jeune, avec des symptômes identiques à ceux du sujet jeune.</li><li>La <strong>schizophrénie à début tardif</strong> :</li><ul><li>Début après <strong>40 ans</strong> (voire très tardif après <strong>60 ans</strong>).</li><li><strong>Prédominance féminine</strong> (<strong>7 femmes pour 1 homme</strong>).</li><li>Cliniquement, elle se caractérise par des <strong>idées délirantes de persécution</strong> et une <strong>symptomatologie hallucinatoire riche</strong> dans toutes les modalités sensorielles, avec peu de désorganisation et de symptômes négatifs.</li></ul></ul>"},{"i":"b04c62b71615","n":70,"o":"70-5","u":"Diagnostic positif","t":"Connaître les spécificités sémiologiques des troubles psychiatriques du sujet âgé","q":"Quelles sont les spécificités sémiologiques d'un épisode dépressif caractérisé (EDC) chez le sujet âgé, comparativement à l'adulte jeune ?","a":"<p>Chez le sujet âgé, l'EDC présente des spécificités sémiologiques :</p><ul><li>Une <strong>douleur morale</strong> avec sentiment d'impuissance et de vide intérieur.</li><li>Des <strong>troubles du comportement</strong> : irritabilité, agressivité, agitation, opposition ou refus de soins.</li><li>D'autres symptômes comme l'<strong>angoisse matinale</strong>, l'<strong>hypochondrie</strong>, les <strong>somatisations</strong>, des plaintes mnésiques, le repli sur soi et l'isolement.</li><li>Moins fréquemment, des <strong>symptômes psychotiques</strong> (idées délirantes de préjudice, persécution, jalousie, culpabilité, hypocondriaques, ou syndrome de Cotard).</li></ul>"},{"i":"c4b0cacb38e5","n":70,"o":"70-5","u":"Diagnostic positif","t":"Connaître les spécificités sémiologiques des troubles psychiatriques du sujet âgé","q":"Quelles sont les particularités de la crise suicidaire chez le sujet âgé ?","a":"<p>La crise suicidaire chez le sujet âgé présente des particularités importantes :</p><ul><li>L'<strong>intentionnalité suicidaire est élevée</strong>, avec une réussite des suicides <strong>50 fois supérieure</strong> à celle d'un jeune.</li><li>Les personnes âgées expriment <strong>rarement</strong> des idées suicidaires.</li><li>Il y a une <strong>faible impulsivité et agressivité</strong>.</li><li>Peu d'antécédents personnels de conduite suicidaire.</li><li>Les moyens employés sont souvent <strong>radicaux</strong>.</li><li><strong>30%</strong> des suicides surviennent chez les plus de <strong>65 ans</strong>, avec une prédominance masculine.</li></ul>"},{"i":"e4d23bbe199e","n":70,"o":"70-5","u":"Diagnostic positif","t":"Connaître les spécificités sémiologiques des troubles psychiatriques du sujet âgé","q":"Quelles sont les spécificités sémiologiques du trouble lié à l'usage d'alcool chez le sujet âgé ?","a":"<p>Le trouble lié à l'usage d'alcool chez le sujet âgé présente des spécificités sémiologiques et des points de vigilance :</p><ul><li>Certains critères d'addiction de l'adulte jeune, comme le retentissement professionnel, ne sont pas toujours applicables.</li><li>Il faut être vigilant au :</li><ul><li>Retentissement fonctionnel.</li><li>Négligence corporelle.</li><li>Troubles du sommeil.</li><li>Symptômes anxio-dépressifs.</li><li>Déficit cognitif.</li><li>Syndrome confusionnel.</li><li>Signes de sevrage à l'alcool.</li></ul></ul>"},{"i":"166de8446e84","n":70,"o":"70-6","u":"Diagnostic positif","t":"Connaître la sémiologie des symptômes psycho-comportementaux chez le sujet âgé dément","q":"Comment les symptômes psycho-comportementaux de la démence chez le sujet âgé sont-ils classés sémiologiquement ?","a":"<p>Les symptômes psycho-comportementaux de la démence (SPCD) chez le sujet âgé sont regroupés en trois catégories sémiologiques principales :</p><ul><li>Les <strong>symptômes de retrait</strong> (SPCD précoces).</li><li>Les <strong>symptômes psychotiques</strong> (SPCD tardifs).</li><li>Les <strong>autres symptômes</strong> (anxiété, agitation, euphorie/désinhibition, etc.).</li></ul>"},{"i":"9457d6e422f2","n":70,"o":"70-6","u":"Diagnostic positif","t":"Connaître la sémiologie des symptômes psycho-comportementaux chez le sujet âgé dément","q":"Quels sont les pièges à éviter concernant le traitement des perturbations de l'identification chez le sujet âgé dément ?","a":"<p>Il est important de ne <strong>pas</strong> traiter les perturbations de l'identification par des <strong>neuroleptiques</strong>.</p>"},{"i":"9a6b778481a0","n":70,"o":"70-6","u":"Diagnostic positif","t":"Connaître la sémiologie des symptômes psycho-comportementaux chez le sujet âgé dément","q":"Quels sont les symptômes de retrait les plus fréquents des SPCD précoces chez le sujet âgé dément ?","a":"<p>Les symptômes de retrait, les plus fréquents (50 % des démences) et souvent précoces, incluent principalement :</p><ul><li>L'<strong>apathie</strong> : réduction quantifiable des initiatives et des activités dirigées vers un but (comportements, cognitions, émotions, interactions sociales), à distinguer de l'anhédonie car le sujet n'en souffre pas.</li><li>Les <strong>symptômes dépressifs</strong> : tristesse, culpabilité, pessimisme, idées de mort.</li></ul>"},{"i":"a29cf409aea6","n":70,"o":"70-6","u":"Diagnostic positif","t":"Connaître la sémiologie des symptômes psycho-comportementaux chez le sujet âgé dément","q":"Décrivez les principales caractéristiques des symptômes psychotiques des SPCD tardifs chez le sujet âgé dément.","a":"<p>Les symptômes psychotiques sont des SPCD plus tardifs, incluant :</p><ul><li>Les <strong>idées délirantes</strong> : le plus souvent de <strong>persécution</strong>, ou des perturbations de l'identification (conviction d'être volé, conviction d'occuper un domicile qui n'est pas le sien), liées aux altérations mnésiques et sensorielles.</li><li>Les <strong>hallucinations</strong> : principalement <strong>visuelles</strong>, favorisées par les déficits sensoriels qui nécessitent une correction.</li></ul>"},{"i":"cd5012b9f650","n":70,"o":"70-6","u":"Diagnostic positif","t":"Connaître la sémiologie des symptômes psycho-comportementaux chez le sujet âgé dément","q":"Quels sont les 'autres' symptômes psycho-comportementaux classiques observés chez le sujet âgé dément ?","a":"<p>Les 'autres' symptômes psycho-comportementaux incluent :</p><ul><li>L'<strong>anxiété</strong> : attaques de panique, ruminations, cris, questionnements répétitifs.</li><li>L'<strong>agitation</strong>, l'<strong>agressivité</strong>, l'<strong>irritabilité</strong> (accès de colère).</li><li>L'<strong>euphorie / désinhibition</strong> : impulsivité et hyper-familiarité avec perte des convenances, évoquant un <strong>syndrome frontal</strong>.</li><li>D'autres manifestations comme les <strong>comportements moteurs aberrants</strong> (stéréotypies), les <strong>troubles du sommeil</strong> et les <strong>troubles de l'appétit</strong>.</li></ul>"},{"i":"e44e242a1763","n":70,"o":"70-6","u":"Diagnostic positif","t":"Connaître la sémiologie des symptômes psycho-comportementaux chez le sujet âgé dément","q":"Quelle est la conduite à tenir devant des hallucinations visuelles chez un sujet âgé ?","a":"<p>Devant des <strong>hallucinations visuelles</strong> chez un sujet âgé, il faut toujours évoquer un <strong>syndrome confusionnel</strong> ou une <strong>démence à corps de Lewy</strong>.</p>"},{"i":"075c6694a245","n":70,"o":"70-9","u":"Prise en charge","t":"Connaître les spécificités du maniement des anxiolytiques et hypnotiques chez le sujet âgé","q":"Quelles sont les spécificités dans le choix des molécules anxiolytiques et hypnotiques chez le sujet âgé ?","a":"<p>Chez le sujet âgé, il convient de privilégier les <strong>benzodiazépines (BZD) à demi-vie courte</strong> et à faibles posologies, telles que l'<strong>oxazépam</strong> ou le <strong>lorazépam</strong>. L'<strong>hydroxyzine</strong> doit être évitée en raison de ses effets anticholinergiques.</p>"},{"i":"4b9a4282f40c","n":70,"o":"70-9","u":"Prise en charge","t":"Connaître les spécificités du maniement des anxiolytiques et hypnotiques chez le sujet âgé","q":"Pourquoi un arrêt progressif des benzodiazépines est-il recommandé chez le sujet âgé ?","a":"<p>L'arrêt progressif des benzodiazépines est essentiel pour <strong>éviter le syndrome de sevrage</strong> (insomnie, anxiété rebond, agitation), <strong>réduire le risque de chutes</strong>, de <strong>troubles cognitifs</strong> et de <strong>dépendance</strong>.</p>"},{"i":"77ce141baa37","n":70,"o":"70-9","u":"Prise en charge","t":"Connaître les spécificités du maniement des anxiolytiques et hypnotiques chez le sujet âgé","q":"Quels sont les principaux effets indésirables des anxiolytiques et hypnotiques chez le sujet âgé ?","a":"<ul><li><strong>Sédation</strong></li><li>Altérations cognitives, <strong>amnésie antérograde</strong>, <strong>syndrome confusionnel</strong></li><li>Risque de <strong>chutes et de fractures</strong></li><li>Dépendance, tolérance, syndrome de sevrage</li></ul>"},{"i":"e57fed2eece5","n":70,"o":"70-9","u":"Prise en charge","t":"Connaître les spécificités du maniement des anxiolytiques et hypnotiques chez le sujet âgé","q":"Quelles sont les modalités d'arrêt des benzodiazépines chez le patient âgé (> 65 ans) ?","a":"<ul><li><strong>Évaluation de la consommation</strong> et réévaluation si prise quotidienne > 30 jours.</li><li><strong>Décision partagée</strong> avec le patient pour l'adhésion au sevrage.</li><li><strong>Évaluation des difficultés</strong> (pathologies associées, facteurs de rechute).</li><li><strong>Prise en charge spécialisée conjointe</strong> si doses très élevées, insomnie rebelle, dépendance ou troubles psychiatriques sévères.</li><li><strong>Arrêt progressif</strong> avec diminution sur 4 à 10 semaines.</li><li><strong>Suivi rapproché</strong> jusqu'à 6 mois après l'arrêt pour prévenir les rechutes.</li></ul>"},{"i":"f1794436a1a0","n":70,"o":"70-9","u":"Prise en charge","t":"Connaître les spécificités du maniement des anxiolytiques et hypnotiques chez le sujet âgé","q":"Quelles sont les durées maximales de prescription des anxiolytiques et hypnotiques chez le sujet âgé ?","a":"<p>La durée maximale de prescription est de <strong>12 semaines pour les anxiolytiques</strong> et de <strong>4 semaines pour les hypnotiques</strong> chez le sujet âgé.</p>"}]};